<?php if(!in_array(http_response_code(),[403,503],true)):if($case):$c=$case;$d=$c['root']['data'];$extra=['id'=>(string)$c['root']['id'],'version'=>$c['version']];$staff=(int)$c['root']['actor_id']===$actor;?>
<section class="card"><div class="sc-row"><h2>Count #<?=(int)$c['root']['id']?> · <?=access_h($d['purpose'])?></h2><span class="sc-badge"><?=access_h(sc_status($c['status']))?></span></div>
<p><?=access_h($c['root']['actor_name'])?> · Started <?=access_h(display_date($c['root']['created_at']))?> UTC</p>
