<?php if($d['parent']):?><p><?php sc_link('Original Count #'.$d['parent'],['id'=>$d['parent']]);?></p><?php endif?>
</section>
<?php if(in_array($c['status'],['counting','ready'],true)&&$staff):?>
<section class="card"><h2>Count Selected Items</h2>
<?php $completedCount=count(array_filter($c['lines'],static fn(array $line):bool=>!empty($line['complete'])));?>
<p><strong><?=$completedCount?> of <?=count($c['lines'])?> items counted.</strong> Enter 0 when there is no saleable stock. A blank quantity means the item still needs to be counted.</p><p>Count saleable stock. Existing reported holds are excluded from the saleable baseline. Keep damaged or expired items secured separately; report them under Non-Sale Issues.</p>
<?php $selectedItem=$itemId&&isset($c['lines'][$itemId])?$itemId:0;if(!$selectedItem)foreach($c['lines'] as $keyId=>$value)if(empty($value['complete'])){$selectedItem=(int)$keyId;break;}if(!$selectedItem)$selectedItem=(int)array_key_first($c['lines']);?><div class="sc-row"><?php foreach($c['lines'] as $item=>$line)sc_link($line['name'].(!empty($line['complete'])?' · Done':''),['id'=>$id,'item'=>$item]);?></div>
<?php foreach($c['lines'] as $item=>$line):if((int)$item!==$selectedItem)continue;?><article class="sc-line" id="stockcount-step" tabindex="-1"><h3><?=access_h($line['name'])?> · <?=!empty($line['complete'])?'Counted '.access_h(sc_qty($line['qty'])):'Not Finished'?></h3>
<?php $window=false;foreach(array_reverse($c['history']) as $event)if(($event['data']['extra_id']??null)==$item){$window=$event['kind']==='count_window';break;}?>
<?php if($window):?><form method="post"><?php sc_fields('finish',$extra+['extra_id'=>(string)$item]);?><p>Counting window started. If stock moves before saving, begin this item again and physically recount it.</p><label>Physical Saleable Quantity *<input type="number" name="qty" min="0" max="9999999999.99" step="0.01" required value="<?=access_h(sc_value('extra_id')===(string)$item?sc_value('qty'):'')?>"></label>
<?php sc_text('Count Note · Include Separately Held Damaged / Expired Quantities','note');sc_check('confirmed','I counted saleable stock and noted damaged or expired items held separately.');?><button type="submit">Save Item Count</button></form><?php endif?>
<form method="post"><?php sc_fields('begin',$extra+['extra_id'=>(string)$item]);?><button class="secondary" type="submit"><?=!empty($line['complete'])||$window?'Begin Item Again':'Begin Counting This Item'?></button></form></article><?php endforeach?>
<?php sc_link('Cancel Unfinished Count',['id'=>$id,'form'=>'cancel']);?></section>
<?php endif?>
<?php if(!$c['blind']):?>
<section class="card"><h2><?=in_array($c['status'],['ready','submitted','disputed','recount'],true)?'Count Comparison':'Count Evidence'?></h2>
<div class="sc-table"><table><thead><tr><th>Item</th><th>Expected At Count (Saleable)</th><th>Counted</th><th>Difference</th><th>Later Movements</th><th>Current Recorded</th><th><?=$c['status']==='approved'?'Current Balance':'After Approval'?></th></tr></thead><tbody>
<?php foreach($c['lines'] as $item=>$line):if(empty($line['complete']))continue;?><tr><th><?=access_h($line['name'])?></th><?php foreach(['expected','qty','difference','later','current','projected'] as $k):?><td><?=$line[$k]===null?'Unavailable':access_h(sc_qty($line[$k]))?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div>
<?php foreach($c['lines'] as $item=>$line):if(empty($line['complete']))continue;?>
<?php if(!$line['available']):?><p>Current comparison unavailable for <?=access_h($line['name'])?>. Original evidence remains available. No new adjustment can be approved for this count.</p><?php endif?>
<?php if((!$line['integrity']||$line['stale'])&&$c['status']!=='approved'):?><p class="error"><?=access_h($line['name'])?>: another adjustment or unexplained change requires a recount.</p><?php endif?>
<?php if(!empty($line['reason'])||!empty($line['note'])):?><p><strong><?=access_h($line['name'].': '.($line['reason']??''))?></strong> · <?=access_h($line['note']??'')?></p><?php endif?><?php endforeach?>
<p>Later sales and deliveries stay intact. Approval applies only the count difference. This creates no payment, expense, stock valuation or staff deduction.</p>
<?php if($c['status']==='approved'):?><h3>Approval Snapshot</h3><p><?=access_h($c['decision']['data']['decision'])?></p><?php foreach($c['decision']['data']['lines'] as $item=>$snapshot):?><p><?=access_h($c['lines'][$item]['name'])?>: <?=access_h(sc_qty($snapshot['before']))?> → <?=access_h(sc_qty($snapshot['after']))?> · Movement <?=$snapshot['movement_id']?(int)$snapshot['movement_id']:'None Needed'?></p><?php endforeach;endif?>
</section>
<?php endif?>
<?php if($c['status']==='ready'&&$staff):?><section class="card"><h2>Explain Differences & Submit</h2><form method="post" enctype="multipart/form-data" data-confirm="Submit this count to Eugene? Stock quantities will not change."><?php sc_fields('submit',$extra);?>
<?php foreach($c['lines'] as $item=>$line):if(!$line['difference'])continue;?><h3><?=access_h($line['name'])?> · Difference <?=access_h(sc_qty($line['difference']))?></h3><label>Reason *<select name="reason_<?=(int)$item?>" required><option value="">Select Reason</option><?php foreach(\Tivoli\Service\StockCountService::REASONS as $reason):?><option <?=sc_value('reason_'.$item)===$reason?'selected':''?>><?=access_h($reason)?></option><?php endforeach?></select></label><?php sc_text('Explanation','note_'.$item,true,$line['note']);endforeach;sc_upload();sc_check('confirmed','These are actual physical counts. Submission does not adjust stock.');?><div class="sc-row"><button type="submit">Submit For Review</button><?php sc_link('Back To Counts',[]);?></div></form></section><?php endif?>
<div class="sc-row">
<?php if($owner&&$c['status']==='submitted')sc_link('Review & Decide',['id'=>$id,'form'=>'approve'],true);if($owner&&in_array($c['status'],['submitted','disputed'],true)){sc_link('Request Recount',['id'=>$id,'form'=>'recount']);sc_link('Dispute',['id'=>$id,'form'=>'dispute']);}if($staff&&$c['status']==='disputed')sc_link('Add Clarification',['id'=>$id,'form'=>'clarify']);?>
<?php if($staff&&$c['status']==='recount'):?><form method="post" data-confirm="Start a new linked count of these same items? The original stays in history."><?php sc_fields('start',['items'=>json_encode(array_keys($c['lines'])),'parent'=>(string)$id,'purpose'=>$d['purpose'],'comment'=>'Recount of #'.$id]);?><button type="submit">Start Linked Recount</button></form><?php endif?>
</div>
<?php if($form):?><section class="card" id="stockcount-form" tabindex="-1"><h2><?=access_h(match($form){'approve'=>'Approve Stock Adjustment','recount'=>'Request A Recount','dispute'=>'Dispute Count','clarify'=>'Append Clarification',default=>'Cancel Unfinished Count'})?></h2><form method="post" enctype="multipart/form-data" data-confirm="Record this decision? Original counts and movements will be retained."><?php sc_fields($form,$extra);if($form==='approve'):?><input type="hidden" name="review_token" value="<?=access_h($c['review_token'])?>"><?php sc_text('Decision / Investigation Note','decision',true);if($staff)sc_text('Self-Review Exception Reason','exception_reason',true);sc_check('verified','I verified the count, explanations and supporting stock records.');sc_check('authorized','I authorize these exact quantity differences. This does not establish staff liability.');else:sc_text($form==='clarify'?'Clarification / Additional Evidence':'Reason / Instructions','reason',true);if($form==='clarify')sc_upload();endif;?><div class="sc-row"><button type="submit"><?=$form==='approve'?'Confirm Approval & Apply Differences':'Record Action'?></button><?php sc_link('Cancel',['id'=>$id]);?></div></form></section><?php endif?>
<section class="card"><h2>Activity & Evidence</h2><ol class="sc-history"><li><strong>Count Started</strong><p><?=access_h($c['root']['actor_name'].' · '.display_date($c['root']['created_at']))?> UTC</p></li><?php foreach($c['history'] as $ev):?><li><strong><?=access_h(ucwords(str_replace('_',' ',substr($ev['kind'],6))))?></strong><p><?=access_h($ev['actor_name'].' · '.display_date($ev['created_at']))?> UTC</p><?php foreach(['reason','decision','self_review_exception'] as $k)if(!empty($ev['data'][$k])):?><p><?=access_h($ev['data'][$k])?></p><?php endif?>
<?php if($ev['kind']==='count_line'):?><p><?=access_h($c['lines'][$ev['data']['extra_id']]['name'])?> · Physical Quantity <?=isset($ev['data']['line'])?access_h(sc_qty($ev['data']['line']['qty'])):'Saved'?></p><?php if(!empty($ev['data']['line']['note'])):?><p><?=access_h($ev['data']['line']['note'])?></p><?php endif;endif?>
<?php if(isset($ev['data']['recount_id']))sc_link('Linked Recount #'.$ev['data']['recount_id'],['id'=>$ev['data']['recount_id']]);if(isset($files[(int)$ev['id']])):?><a href="<?=access_h(access_url('finance-evidence.php?kind=stockcount&id='.(int)$ev['id']))?>">Download Private Evidence</a><?php endif?></li><?php endforeach?></ol></section>
<?php elseif($page==='new'):require __DIR__.'/start.php';?>
<?php else:?><section class="card"><h2><?=access_h($page==='owner'?'Owner Review Queue':($page==='activity'?'Count History':'Stock Count Register'))?></h2><div class="sc-table"><table><thead><tr><th>Count</th><th>Counter</th><th>Started</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><th>#<?=(int)$row['root']['id']?> · <?=access_h($row['root']['data']['purpose'])?></th><td><?=access_h($row['root']['actor_name'])?></td><td><?=access_h(display_date($row['root']['created_at']))?> UTC</td><td><?=access_h(sc_status($row['status']))?></td><td><?php sc_link('Show Details',['id'=>$row['root']['id']]);?></td></tr><?php endforeach?></tbody></table></div><?php if(!$rows):?><p>No counts in this view.</p><?php endif?><?php if($next)sc_link('Older Counts',['before'=>$next,'page'=>$page]);?></section><?php endif;endif?>
</div></div>
